export type Dec = { readonly n: bigint; readonly d: bigint };

const abs = (value: bigint): bigint => (value < 0n ? -value : value);
function gcd(a: bigint, b: bigint): bigint {
  let x = abs(a);
  let y = abs(b);
  while (y !== 0n) { const rest = x % y; x = y; y = rest; }
  return x;
}
