const divD = (a: Dec, b: Dec): Dec | null => (b.n === 0n ? null : dec(a.n * b.d, a.d * b.n));
const cmpD = (a: Dec, b: Dec): number => { const left = a.n * b.d; const right = b.n * a.d; return left < right ? -1 : left > right ? 1 : 0; };
