const SLIDER_NUMBER = /^-?(0|[1-9]\d{0,5})(\.\d{1,3})?$/;
const EXACT_DECIMAL = /^-?(0|[1-9]\d{0,14})(\.\d{1,12})?$/;
const EXACT_FRACTION = /^-?(0|[1-9]\d{0,14})\/[1-9]\d{0,14}$/;

